-- =====================================================================
-- 0003_estimating_seed.sql
-- seed_default_estimating(company_id): starter price book, 10x10 template, and
-- the Home Depot comparison source for one company. Call it at onboarding
-- (service role) and from supabase/seed.sql. Safe to call twice.
--
-- Price sources (catalog_items.price_source):
--   home_depot = read from homedepot.com on 2026-10-23 (source_url kept)
--   market     = NoVA market sell price (quartz), cost is a PLACEHOLDER until you enter your fabricator's price
--   sample     = placeholder: replace in Settings > Price book
-- Cabinet boxes are placeholders: import the vendor price list, then use set_quote_collection().
-- Generated by gen_seed.py - edit the generator, not this file.
-- =====================================================================
create or replace function public.seed_default_estimating(p_company_id uuid)
returns void language plpgsql security invoker set search_path = public as $$
declare
  v_tpl uuid;
