begin
  if exists (select 1 from public.catalog_categories where company_id = p_company_id) then
    return;
  end if;

  insert into public.estimating_settings (company_id) values (p_company_id)
  on conflict (company_id) do nothing;

  insert into public.quote_sections (company_id, name, client_description, sort_order, absorbs_project_costs)
  select p_company_id, v.* from (values
      ('1. Cabinetry', 'Cabinets per the cabinet list, fillers, panels, crown, light rail, toe kick, hardware', 1, false),
      ('2. Countertop', 'Quartz top, edge, sink cutout, faucet holes, template and install', 2, false),
      ('3. Sink & plumbing', 'Sink, faucet, disposal, supply and drain parts, licensed plumber reconnects', 3, false),
      ('4. Lighting & electrical', 'Under-cabinet LED with dimmer, GFCI outlets, licensed electrician', 4, false),
      ('5. Installation', 'Demo, protection, haul-away, cabinet and trim install, appliance hookups, cleanup', 5, true),
      ('6. Permits & fees', 'Permits and inspections where required', 6, false)
  ) as v(name, client_description, sort_order, absorbs);

  insert into public.pick_phases (company_id, name, sort_order)
  select p_company_id, v.* from (values
      ('1. Protect & demo', 1),
      ('2. Layout & prep', 2),
      ('3. Cabinets', 3),
      ('4. Fillers, panels & trim', 4),
      ('5. Countertop template', 5),
      ('6. Plumbing & appliances', 6),
      ('7. Electrical finish', 7),
      ('8. Finish & punch', 8)
  ) as v(name, sort_order);

  insert into public.catalog_categories (company_id, name, cost_category, default_section_id, default_pick_phase_id, sort_order)
  select p_company_id, v.name, v.cost_category, s.id, p.id, v.sort_order
  from (values
      ('Cabinets', 'materials', '1. Cabinetry', '3. Cabinets', 1),
      ('Fillers & trim', 'materials', '1. Cabinetry', '4. Fillers, panels & trim', 2),
      ('Cabinet accessories', 'materials', '1. Cabinetry', '3. Cabinets', 3),
      ('Hardware', 'materials', '1. Cabinetry', '8. Finish & punch', 4),
