      ('Appliance hookup', 'materials', '5. Installation', '6. Plumbing & appliances', 7),
      ('Electrical', 'materials', '4. Lighting & electrical', '7. Electrical finish', 8),
      ('Install consumables', 'materials', '5. Installation', '3. Cabinets', 9),
      ('Demo & protection', 'materials', '5. Installation', '1. Protect & demo', 10),
      ('Labor', 'labor', '5. Installation', null, 11),
      ('Subcontractor', 'subcontractor', '5. Installation', null, 12),
      ('Permit', 'permit', '6. Permits & fees', null, 13)
  ) as v(name, cost_category, section_name, phase_name, sort_order)
  join public.quote_sections s on s.company_id = p_company_id and s.name = v.section_name
  left join public.pick_phases p on p.company_id = p_company_id and p.name = v.phase_name;

