  insert into public.catalog_items (company_id, category_id, code, name, unit, unit_cost_cents, uses_labor_rate,
                                    taxable, is_allowance, vendor, qty_source, cost_category, section_id, notes,
                                    price_source, source_url, source_checked_on, pricing_mode, unit_price_cents)
  select p_company_id, c.id, i.code, i.name, i.unit, i.unit_cost_cents, i.uses_labor_rate, i.taxable,
         i.is_allowance, i.vendor, i.qty_source, i.cost_category, s.id, i.notes,
         i.price_source, i.source_url, i.source_checked_on, i.pricing_mode, i.unit_price_cents
  from _seed_items i
  join public.catalog_categories c on c.company_id = p_company_id and c.name = i.category
  left join public.quote_sections s on s.company_id = p_company_id and s.name = i.section_name
  order by i.sort_order;

  insert into public.quote_templates (company_id, name, description, default_takeoff)
  values (p_company_id, '10x10 L-shape - shaker + quartz',
          'Two 10 ft runs, sink under window + DW on wall A, 30in range + OTR microwave on wall B, 36in fridge opening. Existing appliances reconnected.',
          '{"counter_runs_in": [120, 120], "counter_depth_in": 25.5, "corners": 1, "openings_in": [30], "crown_lf": 22, "light_rail_lf": 14, "toe_kick_lf": 14, "scribe_lf": 12, "doors": 19, "drawers": 6, "led_ft": 12, "led_watts_per_ft": 4, "led_driver_w": 60, "countertop_outlets": 5, "extra_cover_plates": 1, "cabinet_lf": 29.5}'::jsonb)
  returning id into v_tpl;

  insert into public.quote_template_items (company_id, template_id, catalog_item_id, qty, sort_order)
  select p_company_id, v_tpl, ci.id, i.template_qty, i.sort_order
  from _seed_items i
  join public.catalog_categories c on c.company_id = p_company_id and c.name = i.category
  join public.catalog_items ci on ci.company_id = p_company_id and ci.category_id = c.id
                              and ci.code = i.code and ci.name = i.name and ci.collection_id is null
  where i.template_qty is not null
  order by i.sort_order;

  -- Home Depot comparison
  insert into public.comparison_sources (company_id, name, disclaimer)
  values (p_company_id, 'Home Depot', 'Home Depot prices were read from homedepot.com product pages on the date shown, before local tax and delivery, and change often. Home Depot quotes installation and countertops only after an in-home measure ($129, credited to the purchase), so those are not included unless an actual Home Depot quote is entered. Hampton Bay products are the closest stock equivalents, not the same products.')
  returning id into v_hd;

